bundle.vehicle_select:
def rule(f):
    others = f['_all']
    avg = sum(x['agv_cum_travel'] for x in others) / len(others) if others else f['agv_cum_travel']
    return -f['empty_travel'] - f['loaded_travel'] - f['queue_len'] + (avg - f['agv_cum_travel'])

